#!/usr/bin/env bash
# Regenerate VeloMaps.xcodeproj from project.yml. Never hand-edit project.pbxproj.
# Also writes the gitignored VeloMaps/AppSecrets.swift from the Mac keychain (voice-service
# app token); missing token = empty string = the app uses recorded clips / iPhone voice.
set -euo pipefail
cd "$(dirname "$0")/.."
TOKEN=$(security find-generic-password -s velomaps-tts-app-token -w 2>/dev/null || true)
cat > VeloMaps/AppSecrets.swift <<SWIFT
// Generated by scripts/generate.sh from the Mac keychain. Do not commit (gitignored).
enum AppSecrets {
    /// Shared token for the Velo Maps voice service (deters drive-by use; the real limits are
    /// the server's daily character budget and per-IP rate limit).
    static let voiceToken = "$TOKEN"
}
SWIFT
xcodegen generate --quiet
echo "regenerated VeloMaps.xcodeproj"
